head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > accessibility]<br/>MultiSelect 컴포넌트의 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "true 설정 시 MultiSelect 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용합니다.",
        "true 설정 시 컴포넌트가 ul, li 태그로 렌더링되며 aria-activedescendant 등의 접근성 관련 HTML 속성이 추가됩니다.",
        "true 설정 시 위/아래 방향키로 아이템 간 포커스를 이동하고, Space 키로 선택/해제할 수 있습니다.",
        "true 설정 시 Ctrl 키 없이 클릭만으로 아이템을 토글 선택할 수 있습니다.",
        "false (default) 설정 시 웹접근성 지원 기능을 적용하지 않습니다.",
        "false 설정 시 컴포넌트가 table, tr 태그로 렌더링됩니다.",
        "false 설정 시 Ctrl+클릭으로 추가 선택, Shift+클릭으로 범위 선택을 할 수 있습니다.",
        "accessibility=true 이고 singleSelect=true 이면 Enter 키로도 아이템을 선택할 수 있습니다.",
        "accessibility=true 일때 nextTabID 속성을 설정하면 위/아래 방향키 대신 Tab, Shift+Tab 키로 아이템 간 포커스가 이동됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        accessibility : con_accessibility.getText(),
        singleSelect : con_singleSelect.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicMultiSelect(cList);
}



scwin.btn_getAccessibility_onclick = function (e) {
    let rtn = '';

    rtn = target1.render.tagName;
    wf_body_bottom.getObj("scwin").setReturnValue("render tagName : " + rtn);

    rtn = target1.render.className;
    wf_body_bottom.getObj("scwin").setReturnValue("render className : " + rtn);

    let ulElem = document.querySelector("ul[id*='target1_ul']");
    let tableElem = document.querySelector("table[id*='target1_table']");
    let liElem = document.querySelector("li[id*='target1_li_item_0']");
    let trElem = document.querySelector("#" + target1.getID() + " tr");

    if (ulElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("list tag : " + ulElem.tagName);
        wf_body_bottom.getObj("scwin").setReturnValue("list role : " + ulElem.getAttribute('role'));
    }
    if (liElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("item tag : " + liElem.tagName);
        wf_body_bottom.getObj("scwin").setReturnValue("item role : " + liElem.getAttribute('role'));
    }
    if (tableElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("list tag : " + tableElem.tagName);
    }
    if (trElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("item tag : " + trElem.tagName);
    }

    rtn = target1.render.getAttribute('aria-activedescendant');
    wf_body_bottom.getObj("scwin").setReturnValue("aria-activedescendant : " + rtn);
};



scwin.btn_clickItem_onclick = function (e) {
    // accessibility=true: 클릭만으로 토글 선택, false: Ctrl 키 없이 클릭은 단일 선택
    let firstItem;
    let secondItem;

    if (target1.options.accessibility == true) {
        firstItem = document.querySelector("li[id*='target1_li_item_0']");
        secondItem = document.querySelector("li[id*='target1_li_item_1']");
    } else {
        firstItem = document.querySelector("#" + target1.getID() + " tr:nth-child(1)");
        secondItem = document.querySelector("#" + target1.getID() + " tr:nth-child(2)");
    }

    if (firstItem) firstItem.click();
    if (secondItem) secondItem.click();

    let selectedValues = target1.getSelectedValues();
    wf_body_bottom.getObj("scwin").setReturnValue("클릭 후 선택된 값 : " + JSON.stringify(selectedValues));
};



scwin.btn_keyPressSpace_onclick = function (e) {
    // accessibility=true: Space 키로 선택/해제
    if (target1.options.accessibility != true) {
        wf_body_bottom.getObj("scwin").setReturnValue("accessibility=false 에서는 동작하지 않습니다.");
        return;
    }

    let ulElem = document.querySelector("ul[id*='target1_ul']");
    if (!ulElem) return;

    ulElem.focus();
    let liElem = document.querySelector("li[id*='target1_li_item_0']");
    if (liElem) liElem.click();

    // Space 키 이벤트 디스패치
    let spaceEvent = new KeyboardEvent('keydown', { key: ' ', code: 'Space', keyCode: 32, which: 32, bubbles: true });
    ulElem.dispatchEvent(spaceEvent);

    let selectedValues = target1.getSelectedValues();
    wf_body_bottom.getObj("scwin").setReturnValue("Space 키 입력 후 선택된 값 : " + JSON.stringify(selectedValues));
};



scwin.btn_keyPressEnter_onclick = function (e) {
    // accessibility=true 이고 singleSelect=true 이면 Enter 키로도 아이템 선택
    if (target1.options.accessibility != true || target1.options.singleSelect != true) {
        wf_body_bottom.getObj("scwin").setReturnValue("accessibility=true 이고 singleSelect=true 인 경우에만 동작합니다.");
        return;
    }

    let ulElem = document.querySelector("ul[id*='target1_ul']");
    if (!ulElem) return;

    ulElem.focus();
    let enterEvent = new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true });
    ulElem.dispatchEvent(enterEvent);

    let selectedValues = target1.getSelectedValues();
    wf_body_bottom.getObj("scwin").setReturnValue("Enter 키 입력 후 선택된 값 : " + JSON.stringify(selectedValues));
};



scwin.btn_keyArrow_onclick = function (e) {
    // accessibility=true: 위/아래 방향키로 아이템 간 포커스 이동
    if (target1.options.accessibility != true) {
        wf_body_bottom.getObj("scwin").setReturnValue("accessibility=false 에서는 동작하지 않습니다.");
        return;
    }

    let ulElem = document.querySelector("ul[id*='target1_ul']");
    if (!ulElem) return;

    ulElem.focus();
    let downEvent = new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', keyCode: 40, which: 40, bubbles: true });
    ulElem.dispatchEvent(downEvent);

    let activeId = ulElem.getAttribute('aria-activedescendant');
    wf_body_bottom.getObj("scwin").setReturnValue("ArrowDown 후 aria-activedescendant : " + activeId);
};
